  );
}

import { HttpError } from "@fleetly/ui-component-core/data";
import { Link } from "@tanstack/react-router";
import { ArrowLeft, RefreshCw } from "lucide-react";
import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";
import { Error403 } from "./error-403";
import { Error404 } from "./error-404";
import { Error500 } from "./error-500";

export interface RouteErrorBoundaryProps {
  error: unknown;
  /** router 的 reset（重试当前路由） */
  reset?: () => void;
}

function errorStatus(error: unknown): number | undefined {
  if (error instanceof HttpError) {
    return error.status;
  }
  if (typeof error === "object" && error !== null && "status" in error) {
    const status = Number((error as { status: unknown }).status);
    return Number.isNaN(status) ? undefined : status;
  }
  return undefined;
}

function defaultMessage(error: unknown): ReactNode {
  if (error instanceof Error && error.message) {
    return error.message;
  }
  return undefined;
}

/**
 * 路由级错误边界（TanStack Router errorComponent / defaultErrorComponent 适配）：
 * HttpError 403/404 分档渲染对应页面，其余（含 5xx 与未知）渲染 500 + 错误信息 + 重试。
 */
export function RouteErrorBoundary({ error, reset }: RouteErrorBoundaryProps) {
  const status = errorStatus(error);
  const actions = (
    <div className="flex items-center gap-2">
      {reset ? (
        <Button variant="outline" size="sm" onClick={reset}>
          <RefreshCw data-icon="inline-start" />
          重试
        </Button>
      ) : null}
      <Button size="sm" render={<Link to="/" />}>
        <ArrowLeft data-icon="inline-start" />
        返回首页
      </Button>
    </div>
  );

  if (status === 403) {
    return <Error403 message={defaultMessage(error)} action={actions} />;
  }
  if (status === 404) {
    return <Error404 message={defaultMessage(error)} action={actions} />;
  }
  return <Error500 message={defaultMessage(error) ?? undefined} action={actions} />;
}

import { HttpError, type HttpErrorKind } from "@fleetly/ui-component-core/data";
import {
  Ban,
  KeyRound,
  Lock,
  type LucideIcon,
  RefreshCw,
  SearchX,
  ServerCrash,
  TriangleAlert,
  WifiOff,
} from "lucide-react";
import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";

export interface ErrorStateCopy {
  kind: HttpErrorKind | "network" | "unknown";
  title: string;
  description: string;
}

const copyTable: Record<
  ErrorStateCopy["kind"],
  { title: string; description: string; icon: LucideIcon }
> = {
  unauthorized: { title: "未登录或登录已过期", description: "请重新登录后继续。", icon: KeyRound },
  forbidden: {
    title: "没有权限访问",
    description: "你的账号没有执行此操作的权限，请联系管理员。",
    icon: Lock,
  },
  "not-found": { title: "内容不存在", description: "请求的资源不存在或已被删除。", icon: SearchX },
  conflict: {
    title: "数据冲突",
    description: "记录已被他人修改，请刷新后重试。",
    icon: TriangleAlert,
  },
  server: { title: "服务端错误", description: "服务器开小差了，请稍后重试。", icon: ServerCrash },
  network: {
    title: "网络错误",
    description: "无法连接到服务器，请检查网络后重试。",
    icon: WifiOff,
  },
  unknown: { title: "出错了", description: "发生意外错误，请重试。", icon: TriangleAlert },
  other: { title: "请求失败", description: "请求未能完成，请重试。", icon: Ban },
};

function copyEntry(kind: ErrorStateCopy["kind"]) {
  return (
    copyTable[kind] ??
    copyTable.unknown ?? {
      title: "出错了",
      description: "发生意外错误，请重试。",
      icon: TriangleAlert,
    }
  );
}

/** HttpError 分档文案（401/403/404/409/5xx/网络/未知） */
export function errorStateCopy(error: unknown): ErrorStateCopy {
  let kind: ErrorStateCopy["kind"];
  if (error instanceof HttpError) {
    kind = error.kind;
  } else if (typeof error === "object" && error !== null && "status" in error) {
    // duck-typing：宿主可能用结构兼容的错误对象
    const status = Number((error as { status: unknown }).status);
    const asHttp = new HttpError(Number.isNaN(status) ? 0 : status, "");
    kind = status >= 500 ? "server" : asHttp.kind;
  } else if (error instanceof TypeError) {
    // fetch 网络失败在浏览器中抛 TypeError
    kind = "network";
  } else {
    kind = "unknown";
  }
  const entry = copyEntry(kind);
  return { kind, title: entry.title, description: entry.description };
}

export interface ErrorStateProps {
  error?: unknown;
  onRetry?: () => void;
  retryLabel?: string;
  /** 额外动作（如「返回首页」） */
  action?: ReactNode;
  className?: string;
}

/** 错误态：按 HttpError 分档文案 + 重试 */
export function ErrorState({
  error,
  onRetry,
  retryLabel = "重试",
  action,
  className,
}: ErrorStateProps) {
  const copy = errorStateCopy(error);
  const Icon = copyEntry(copy.kind).icon;

  return (
    <div
      role="alert"
      data-slot="error-state"
      className={`flex flex-col items-center justify-center gap-3 px-6 py-16 text-center ${className ?? ""}`}
    >
      <div className="bg-status-danger-bg text-status-danger flex size-11 items-center justify-center rounded-full">
        <Icon className="size-5" />
      </div>
      <div className="flex flex-col gap-1">
        <p className="text-sm font-medium">{copy.title}</p>
        <p className="text-muted-foreground max-w-sm text-[13px]">{copy.description}</p>
      </div>
      {error instanceof HttpError && error.status > 0 ? (
        <p className="text-muted-foreground/70 font-mono text-xs">HTTP {error.status}</p>
      ) : null}
      {onRetry || action ? (
        <div className="mt-2 flex items-center gap-2">
          {onRetry ? (
            <Button variant="outline" size="sm" onClick={onRetry}>
              <RefreshCw data-icon="inline-start" />
              {retryLabel}
            </Button>
          ) : null}
          {action}
        </div>
      ) : null}
    </div>
  );
}

import {
  type DateTimePrefs,
  formatAbsolute,
  formatRelative,
  useDateTimePrefs,
  useNow,
} from "@fleetly/ui-component-core/datetime";
import { cn } from "cn";

function toIsoString(value: string | number | Date): string | undefined {
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? undefined : date.toISOString();
}

export interface RelativeTimeProps {
  value: string | number | Date;
  /** 活渲染间隔，默认 30s；传 0 关闭（渲染一次） */
  intervalMs?: number;
  className?: string;
}

/**
 * 相对时间（useNow 活渲染）：正文相对格式，title/dateTime 携带时区感知的绝对格式。
 */
export function RelativeTime({ value, intervalMs = 30_000, className }: RelativeTimeProps) {
  const { prefs } = useDateTimePrefs();
  const now = useNow(intervalMs);
  const absolutePrefs: DateTimePrefs = {
    ...prefs,
    absolutePattern: prefs.absolutePattern ?? "full",
  };

  const relative = formatRelative(value, now);
  const absolute = formatAbsolute(value, absolutePrefs);
  const iso = toIsoString(value);

  return (
    <time
      dateTime={iso}
      title={absolute}
      className={cn("text-muted-foreground text-[13px] tabular-nums", className)}
    >
      {relative}
    </time>
  );
}

