import type { CrumbResolve } from "@fleetly/ui-component-core/router";
import { useCrumbs } from "@fleetly/ui-component-core/router";
import { Link } from "@tanstack/react-router";
import { Fragment } from "react";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";

/**
 * 面包屑（core useCrumbs 派生）：staticData.title 优先，租户段经 resolve.tenant 反查名称。
 * 末段渲染为当前页；移动端只显示末段。
 */
export function Breadcrumbs({ resolve }: { resolve?: CrumbResolve }) {
  const crumbs = useCrumbs(resolve);
  if (crumbs.length === 0) {
    return null;
  }

  return (
    <Breadcrumb>
      <BreadcrumbList>
        {crumbs.map((crumb, index) => {
          const last = index === crumbs.length - 1;
          return (
            <Fragment key={`${crumb.to ?? crumb.label}-${index}`}>
              <BreadcrumbItem className={last ? "" : "hidden sm:inline-flex"}>
                {last || !crumb.to ? (
                  <BreadcrumbPage className="text-foreground">{crumb.label}</BreadcrumbPage>
                ) : (
                  <BreadcrumbLink render={<Link to={crumb.to} />}>{crumb.label}</BreadcrumbLink>
                )}
              </BreadcrumbItem>
              {!last ? <BreadcrumbSeparator className="hidden sm:block" /> : null}
            </Fragment>
          );
        })}
      </BreadcrumbList>
    </Breadcrumb>
  );
}

import { useNavigate } from "@tanstack/react-router";
import type { LucideIcon } from "lucide-react";
import { useEffect } from "react";
import {
  Command,
  CommandEmpty,
  CommandGroup as CommandGroupUI,
  CommandInput,
  CommandItem,
  CommandList,
  CommandShortcut,
} from "@/components/ui/command";
import { Dialog, DialogContent, DialogDescription, DialogTitle } from "@/components/ui/dialog";

export interface CommandItemDef {
  id: string;
  label: string;
  icon?: LucideIcon;
  /** 搜索匹配关键词 */
  keywords?: string[];
  /** 导航目标（优先）；与 run 二选一 */
  to?: string;
  /** 自定义动作 */
  run?: () => void;
}

export interface CommandGroupDef {
  label: string;
  items: CommandItemDef[];
}

export interface CommandPaletteProps {
  groups: CommandGroupDef[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** 触发快捷键（默认 ⌘K / Ctrl+K 全局监听） */
  shortcutEnabled?: boolean;
}

/**
 * ⌘K 全局命令面板：groups 内 item.to 走路由导航，item.run 执行自定义动作。
 * 由宿主持有 open 状态（TopBar 的搜索按钮与快捷键都会触发）。
 */
export function CommandPalette({
  groups,
  open,
  onOpenChange,
  shortcutEnabled = true,
}: CommandPaletteProps) {
  const navigate = useNavigate();

  useEffect(() => {
    if (!shortcutEnabled) {
      return;
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        onOpenChange(!open);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open, onOpenChange, shortcutEnabled]);

  const handleSelect = (item: CommandItemDef) => {
    onOpenChange(false);
    if (item.to !== undefined) {
      navigate({ to: item.to });
    } else {
      item.run?.();
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="top-20 translate-y-0 overflow-hidden p-0 sm:max-w-lg">
        <DialogTitle className="sr-only">命令面板</DialogTitle>
        <DialogDescription className="sr-only">搜索页面或执行动作</DialogDescription>
        <Command>
          <CommandInput placeholder="输入命令或搜索…" />
          <CommandList>
            <CommandEmpty>没有匹配的结果</CommandEmpty>
            {groups.map((group) => (
              <CommandGroupUI key={group.label} heading={group.label}>
                {group.items.map((item) => {
                  const Icon = item.icon;
                  return (
                    <CommandItem
                      key={item.id}
                      value={[item.label, ...(item.keywords ?? [])].join(" ")}
                      onSelect={() => handleSelect(item)}
                    >
                      {Icon ? <Icon /> : null}
                      <span>{item.label}</span>
                      {item.to !== undefined ? <CommandShortcut>跳转</CommandShortcut> : null}
                    </CommandItem>
                  );
                })}
              </CommandGroupUI>
            ))}
          </CommandList>
        </Command>
      </DialogContent>
    </Dialog>
  );
}

